# System.Runtime.Intrinsics.X86.Avx512F — loads, stores, broadcasts and the masked forms. An
# integer vector loads and stores as 512 bits whatever its lane type; the aligned forms
# fault below 64-byte alignment, as in .NET (the exercise aligns its buffers to 64 bytes on
# both sides). The masked forms take the mask as a vector whose lanes' sign bits select
# (VPMOVD2M / VPMOVQ2M, as the JIT imports them): a masked load reads only the selected
# lanes and takes the others from the merge operand, a masked store writes only the selected
# lanes; CompressStore writes the selected lanes of the value contiguously, ExpandLoad reads
# contiguous lanes into the selected positions and takes the others from the merge operand.
# The broadcasts repeat lane 0 of a register, or the 128 or 256 bits at a pointer.
target = avx512f,avx512bw,avx512dq,avx512vl
LoadVector512(p{T}) @ref(Vector512.Load($0)) = _mm512_loadu_si512((const void*)$0) for T in i8,u8,i16,u16,i32,u32,i64,u64
LoadVector512(p{T}) @ref(Vector512.Load($0)) = _mm512_loadu_{ps|pd}($0) for T in f32,f64
LoadAlignedVector512(p{T}) @ref(Vector512.Load($0)) = _mm512_load_si512((const void*)$0) for T in i8,u8,i16,u16,i32,u32,i64,u64
LoadAlignedVector512(p{T}) @ref(Vector512.Load($0)) = _mm512_load_{ps|pd}($0) for T in f32,f64
LoadAlignedVector512NonTemporal(p{T}) @ref(Vector512.Load($0)) = _mm512_stream_load_si512((void*)$0) for T in i8,u8,i16,u16,i32,u32,i64,u64
Store(p{T},v512{T}) = _mm512_storeu_si512((void*)$0, $1) for T in i8,u8,i16,u16,i32,u32,i64,u64
Store(p{T},v512{T}) = _mm512_storeu_{ps|pd}($0, $1) for T in f32,f64
StoreAligned(p{T},v512{T}) = _mm512_store_si512((void*)$0, $1) for T in i8,u8,i16,u16,i32,u32,i64,u64
StoreAligned(p{T},v512{T}) = _mm512_store_{ps|pd}($0, $1) for T in f32,f64
StoreAlignedNonTemporal(p{T},v512{T}) = _mm512_stream_si512((__m512i*)$0, $1) for T in i8,u8,i16,u16,i32,u32,i64,u64
StoreAlignedNonTemporal(p{T},v512{T}) = _mm512_stream_{ps|pd}($0, $1) for T in f32,f64
MaskLoad(p{T},v512{T},v512{T}) @ref(Vector512.ConditionalSelect(Vector512.IsNegative($1.As<{cs}, {scs}>()).As<{scs}, {cs}>(), Vector512.Load($0), $2)) = _mm512_mask_loadu_epi{bits}($2, _mm512_movepi{bits}_mask($1), (const void*)$0) for T in i32,u32,i64,u64
MaskLoad(p{T},v512{T},v512{T}) @ref(Vector512.ConditionalSelect(Vector512.IsNegative($1), Vector512.Load($0), $2)) = _mm512_mask_loadu_{ps|pd}($2, _mm512_movepi{bits}_mask($1:{sT}), (const void*)$0) for T in f32,f64
MaskLoadAligned(p{T},v512{T},v512{T}) @ref(Vector512.ConditionalSelect(Vector512.IsNegative($1.As<{cs}, {scs}>()).As<{scs}, {cs}>(), Vector512.Load($0), $2)) = _mm512_mask_load_epi{bits}($2, _mm512_movepi{bits}_mask($1), (const void*)$0) for T in i32,u32,i64,u64
MaskLoadAligned(p{T},v512{T},v512{T}) @ref(Vector512.ConditionalSelect(Vector512.IsNegative($1), Vector512.Load($0), $2)) = _mm512_mask_load_{ps|pd}($2, _mm512_movepi{bits}_mask($1:{sT}), (const void*)$0) for T in f32,f64
MaskStore(p{T},v512{T},v512{T}) = _mm512_mask_storeu_epi{bits}((void*)$0, _mm512_movepi{bits}_mask($1), $2) for T in i32,u32,i64,u64
MaskStore(p{T},v512{T},v512{T}) = _mm512_mask_storeu_{ps|pd}((void*)$0, _mm512_movepi{bits}_mask($1:{sT}), $2) for T in f32,f64
MaskStoreAligned(p{T},v512{T},v512{T}) = _mm512_mask_store_epi{bits}((void*)$0, _mm512_movepi{bits}_mask($1), $2) for T in i32,u32,i64,u64
MaskStoreAligned(p{T},v512{T},v512{T}) = _mm512_mask_store_{ps|pd}((void*)$0, _mm512_movepi{bits}_mask($1:{sT}), $2) for T in f32,f64
CompressStore(p{T},v512{T},v512{T}) = _mm512_mask_compressstoreu_epi{bits}((void*)$0, _mm512_movepi{bits}_mask($1), $2) for T in i32,u32,i64,u64
CompressStore(p{T},v512{T},v512{T}) = _mm512_mask_compressstoreu_{ps|pd}((void*)$0, _mm512_movepi{bits}_mask($1:{sT}), $2) for T in f32,f64
ExpandLoad(p{T},v512{T},v512{T}) = _mm512_mask_expandloadu_epi{bits}($2, _mm512_movepi{bits}_mask($1), (const void*)$0) for T in i32,u32,i64,u64
ExpandLoad(p{T},v512{T},v512{T}) = _mm512_mask_expandloadu_{ps|pd}($2, _mm512_movepi{bits}_mask($1:{sT}), (const void*)$0) for T in f32,f64
BroadcastScalarToVector512(v128{T}) @ref(Vector512.Create($0.GetElement(0))) = _mm512_broadcastd_epi32($0) for T in i32,u32
BroadcastScalarToVector512(v128{T}) @ref(Vector512.Create($0.GetElement(0))) = _mm512_broadcastq_epi64($0) for T in i64,u64
BroadcastScalarToVector512(v128f32) @ref(Vector512.Create($0.GetElement(0))) = _mm512_broadcastss_ps($0)
BroadcastScalarToVector512(v128f64) @ref(Vector512.Create($0.GetElement(0))) = _mm512_broadcastsd_pd($0)
BroadcastVector128ToVector512(p{T}) @ref(Vector512.Create(Vector256.Create(Vector128.Load($0), Vector128.Load($0)), Vector256.Create(Vector128.Load($0), Vector128.Load($0)))) = _mm512_broadcast_i32x4(_mm_loadu_si128((const __m128i*)$0)) for T in i32,u32
BroadcastVector128ToVector512(pf32) @ref(Vector512.Create(Vector256.Create(Vector128.Load($0), Vector128.Load($0)), Vector256.Create(Vector128.Load($0), Vector128.Load($0)))) = _mm512_broadcast_f32x4(_mm_loadu_ps($0))
BroadcastVector256ToVector512(p{T}) @ref(Vector512.Create(Vector256.Load($0), Vector256.Load($0))) = _mm512_broadcast_i64x4(_mm256_loadu_si256((const __m256i*)$0)) for T in i64,u64
BroadcastVector256ToVector512(pf64) @ref(Vector512.Create(Vector256.Load($0), Vector256.Load($0))) = _mm512_broadcast_f64x4(_mm256_loadu_pd($0))
